window.addEventListener("message",async n=>{if(n.source!==window)return;const{type:o,requestId:t,payload:a}=n.data||{};if(o!=null&&o.startsWith("PINSTR_NIP07_")){if(o==="PINSTR_NIP07_CHECK"&&window.postMessage({type:"PINSTR_NIP07_RESPONSE",requestId:t,payload:{available:typeof window.nostr<"u"}},"*"),o==="PINSTR_NIP07_GET_PUBLIC_KEY")try{if(!window.nostr)throw new Error("NIP-07 extension not available");const e=await window.nostr.getPublicKey();window.postMessage({type:"PINSTR_NIP07_RESPONSE",requestId:t,payload:{pubkey:e}},"*")}catch(e){window.postMessage({type:"PINSTR_NIP07_RESPONSE",requestId:t,payload:{error:e instanceof Error?e.message:"Failed to get public key"}},"*")}if(o==="PINSTR_NIP07_SIGN_EVENT")try{if(!window.nostr)throw new Error("NIP-07 extension not available");const e=await window.nostr.signEvent(a.event);window.postMessage({type:"PINSTR_NIP07_RESPONSE",requestId:t,payload:{signedEvent:e}},"*")}catch(e){window.postMessage({type:"PINSTR_NIP07_RESPONSE",requestId:t,payload:{error:e instanceof Error?e.message:"Failed to sign event"}},"*")}}});window.postMessage({type:"PINSTR_NIP07_READY"},"*");
